            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterE = (aWandererG + RotL64(aCross, 13U)) + 0xB5E49A5C3294F8D0ULL;
            aOrbiterD = ((aWandererF + RotL64(aScatter, 53U)) + RotL64(aCarry, 27U)) + 0xBDE8DDFD511B6161ULL;
            aOrbiterH = ((aWandererK + RotL64(aPrevious, 19U)) + 0xE93873DEA130C52BULL) + aOASaltB[((aIndex + 471U)) & S_SALT1];
