            //
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 35U)) + 0x05F77EA517290753ULL) + aOASaltC[((aIndex + 197U)) & S_SALT1];
            aOrbiterJ = ((aWandererJ + RotL64(aCross, 29U)) + 0x86C93EF93CA9EABDULL) + aOASaltG[((aIndex + 160U)) & S_SALT1];
            aOrbiterF = ((aWandererB + RotL64(aIngress, 41U)) + 0xA975136A2033AA4DULL) + aOASaltD[((aIndex + 13U)) & S_SALT1];
