            aOrbiterE = (aWandererK + RotL64(aScatter, 12U)) + 0x1B8F706ED4E434E3ULL;
            aOrbiterH = (((aWandererC + RotL64(aCross, 23U)) + RotL64(aCarry, 3U)) + 0x12FB4D06C486E8EDULL) + aOASaltE[(((511U - aIndex) + 155U)) & S_SALT1];
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0xB57B996910AC9745ULL) + aOUSaltB[(((511U - aIndex) + 455U)) & S_SALT1];
