            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x266C786FC498F75EULL) + aOUSaltC[(((511U - aIndex) + 391U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x2505D3DBD4E71B55ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x6824944C633C4431ULL), 11U);
            //
            aIngress = aOrbiterH ^ RotL64(aOrbiterA, 47U);
            aIngress = aIngress + (RotL64(aOrbiterJ, 57U) ^ aOrbiterE);
            aIngress = aIngress + (RotL64(aOrbiterF, 12U) ^ aOrbiterI);
            aIngress = aIngress + RotL64(aOrbiterD, 19U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererH = aWandererH + (((RotL64(aIngress, 35U) + RotL64(aOrbiterA, 21U)) + aOrbiterJ) + aWUSaltC[((aIndex + 382U)) & S_SALT1]);
            aWandererC = aWandererC ^ (((RotL64(aScatter, 3U) + RotL64(aOrbiterE, 35U)) + aOrbiterF) + aWUSaltA[(((511U - aIndex) + 288U)) & S_SALT1]);
