            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 30U) + RotL64(aIngress, 43U)) ^ (RotL64(aCarry, 57U) + RotL64(aPrevious, 5U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterE = (aWandererG + RotL64(aIngress, 21U)) + 0xCF0EC893A3A5455EULL;
            aOrbiterC = (((aWandererI + RotL64(aPrevious, 3U)) + RotL64(aCarry, 43U)) + 0xF12BD1FB7221657AULL) + aOASaltD[((aIndex + 391U)) & S_SALT1];
            aOrbiterK = (aWandererC + RotL64(aScatter, 43U)) + 0x847A5828BA72EA2DULL;
            aOrbiterF = ((aWandererH + RotL64(aCross, 57U)) + 0xB41A12DC64CDE602ULL) + aOASaltE[(((511U - aIndex) + 88U)) & S_SALT1];
            aOrbiterH = (aWandererA + RotL64(aPrevious, 10U)) + 0xBAB68349AF0B64C2ULL;
            aOrbiterJ = (((aWandererD + RotL64(aCross, 27U)) + RotL64(aCarry, 29U)) + 0xD7E9E894FC4F8718ULL) + aOASaltC[((aIndex + 477U)) & S_SALT1];
            aOrbiterG = (((aWandererJ + RotL64(aIngress, 51U)) + RotL64(aCarry, 13U)) + 0x247DB7D86F7D6228ULL) + aOASaltB[((aIndex + 401U)) & S_SALT1];
            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0x9C50FE02B6A886A8ULL) + aOUSaltC[(((511U - aIndex) + 360U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterE) ^ 0x930D43E84E5ADA67ULL) ^ aOUSaltD[((aIndex + 216U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x05D2F794B2429929ULL), 51U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x40AA1D1E51770931ULL) + aOUSaltB[((aIndex + 173U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x8F9EFB9428BB7AACULL;
            aOrbiterH = RotL64((aOrbiterH * 0xB4736B64813CA55BULL), 43U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xD696D66C90B220A3ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x8AD9ABEF4D86A425ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x307AA43F29D333D5ULL), 19U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterF) + 0x88F6513B5FB13A7DULL) + aOUSaltG[(((511U - aIndex) + 469U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x580930A1C674F106ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5F43B8D2506AE357ULL), 27U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterE) + 0x251D86D16EF4E037ULL) + aOUSaltE[(((511U - aIndex) + 325U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xD5C60CBFAA04D5A6ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xC1789CE8EC4B936FULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x34BEC29BAAFE3071ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x011DD3A9CFBBCF99ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x217848CA2562941BULL), 3U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0x9BC4416DBE14F47AULL) + aOUSaltF[((aIndex + 111U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0xD137A83A4CBE23C9ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x51D6719AE4E735EBULL), 11U);
            //
            aIngress = aOrbiterC ^ RotL64(aOrbiterF, 3U);
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterG, 29U));
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterE, 44U));
            aIngress = aIngress + RotL64(aOrbiterH, 21U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererJ = aWandererJ + (((RotL64(aCross, 58U) + RotL64(aOrbiterG, 29U)) + aOrbiterC) + aWUSaltD[(((511U - aIndex) + 102U)) & S_SALT1]);
            aWandererH = aWandererH ^ (((RotL64(aScatter, 3U) + RotL64(aOrbiterH, 43U)) + aOrbiterJ) + aWUSaltA[(((511U - aIndex) + 379U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aIngress, 41U) + aOrbiterK) + RotL64(aOrbiterE, 50U));
