            aOrbiterI = ((aWandererH + RotL64(aCross, 37U)) + 0xD0F3A5B0D354368EULL) + aOASaltG[(((511U - aIndex) + 444U)) & S_SALT1];
            aOrbiterJ = ((aWandererA + RotL64(aIngress, 12U)) + RotL64(aCarry, 21U)) + 0xACDFB3DB79748437ULL;
            aOrbiterK = (((aWandererE + RotL64(aPrevious, 47U)) + RotL64(aCarry, 11U)) + 0x9C5386A5FBD1123FULL) + aOASaltC[((aIndex + 23U)) & S_SALT1];
            aOrbiterH = (aWandererC + RotL64(aScatter, 23U)) + 0x679A1327725054D3ULL;
            aOrbiterD = ((aWandererF + RotL64(aCross, 43U)) + RotL64(aCarry, 39U)) + 0x7A1A6453213EFC53ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x152CD77C8F2EC1E2ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterC) ^ 0xE217B717964E835CULL) ^ aOUSaltA[(((511U - aIndex) + 280U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x9E2C37CDBD7D8159ULL), 57U);
